#include <iostream>
#include <algorithm>
#include <cstdlib>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll x1, x2, a, b;
    cin >> x1 >> x2 >> a >> b;

    ll d = x2 - x1;

    if (d < 0) {
        swap(a, b);
        b = -b;
        a = -a;
        d = -d;
    }

    if (a <= d && d <= b) {
        cout << "FIRST\n" << x2 << '\n';
    } else if (a < 0 && llabs(a) >= llabs(b)) {
        cout << "DRAW\n";
    } else if (a <= 0 && 0 <= b) {
        cout << "DRAW\n";
    } else {
        a = max(1LL, a);
        ll v = d % (a + b);

        if (v == 0) {
            cout << "SECOND\n";
        } else if (a <= v && v <= b) {
            cout << "FIRST\n"
                 << x1 + ((x2 - x1 < 0) ? -v : v) << '\n';
        } else {
            cout << "DRAW\n";
        }
    }

    return 0;
}

